import { Scene, Path, Instanced, Color, Vec3, Quaternion } from "retiam";

export class VectorSwarmScene extends Scene {
    public async run() {
        this.camera.position.set([0, 0, 100]);
        this.clearColor(new Color(0.02, 0.02, 0.04, 1.0));

        // 1. Define vector SVG path
        const svg = `
            M 0 -12 C 4 -6, 8 -3, 12 0 C 8 3, 4 6, 0 12
            C -4 6, -8 3, -12 0 C -8 -3, -4 -6, 0 -12 Z
        `;

        // 2. Create template in 'fast' mode
        const template = new Path(svg, {
            method: 'fast',
            fill: new Color(0.2, 0.6, 1.0, 0.7),
            stroke: new Color(1.0, 1.0, 1.0, 0.95),
            stroke_width: 0.5
        });

        // 3. Create 5,000 instances
        const count = 5000;
        const swarm = new Instanced(template, count);
        this.add(swarm);

        // 4. Update instances per frame
        const pos = new Vec3();
        this.always(() => {
            const time = this.time * 0.001;

            for (let i = 0; i < count; i++) {
                const angle = i * 2.39996 + time * 0.2; // Golden angle + rotation
                const radius = 1.2 * Math.sqrt(i + 1);

                pos.set(radius * Math.cos(angle), radius * Math.sin(angle), 0);
                swarm.setInstancePosition(i, pos);
                swarm.setInstanceRotation(i, Quaternion.fromEuler(0, 0, angle));
                swarm.setInstanceScale(i, 0.15 + 0.05 * Math.sin(time * 2.0 + i));
                swarm.setInstanceColor(i, new Color(
                    Math.sin(angle) * 0.5 + 0.5,
                    Math.cos(angle * 0.5) * 0.5 + 0.5,
                    1.0,
                    0.8
                ));
            }

            swarm.isDirty = true; // Stream updates to GPU
            this.invalidate();
        });
    }
}

import { Scene, Model, Math3D, Instanced, Vec3, Quaternion, Color } from "retiam";

export class AsteroidFieldScene extends Scene {
    public async run() {
        this.camera.position.set([0, 50, 150]);

        // 1. Create base 3D cube model
        const baseCube = new Model(Math3D.createCube(1.0));
        baseCube.material.color = new Float32Array([0.8, 0.8, 0.8]);
        baseCube.material.roughness = 0.3;

        // 2. Create 20,000 instanced cubes
        const count = 20000;
        const asteroids = new Instanced(baseCube, count);
        this.add(asteroids);

        // 3. Populate positions in a 3D ring
        const pos = new Vec3();
        for (let i = 0; i < count; i++) {
            const theta = Math.random() * Math.PI * 2;
            const r = 40 + Math.random() * 60;
            const y = (Math.random() - 0.5) * 20;

            pos.set(r * Math.cos(theta), y, r * Math.sin(theta));
            asteroids.setInstancePosition(i, pos);
            asteroids.setInstanceScale(i, 0.2 + Math.random() * 0.8);
            asteroids.setInstanceRotation(i, Quaternion.fromEuler(
                Math.random() * Math.PI,
                Math.random() * Math.PI,
                Math.random() * Math.PI
            ));
        }

        asteroids.isDirty = true;
    }
}

import { Scene, Circle, Instanced, ComputeKernel, Res, createBuffer } from "retiam";

export class ComputeParticlesScene extends Scene {
    public async run() {
        const count = 100000; // 100k instances!
        const baseCircle = new Circle(0.2);
        const instanced = new Instanced(baseCircle, count);
        this.add(instanced);

        // Prepare geometry and retrieve GPU storage buffer
        instanced.geo.prepare(this);
        const instanceBuffer = instanced.getInstanceGPUBuffer();

        // Time uniform buffer
        const timeBuffer = createBuffer(this.device, GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST, 4);

        // WebGPU Compute Kernel
        const kernel = new ComputeKernel({
            "instances": Res.buffer("array<vec4f>", instanceBuffer, "read_write"),
            "params": Res.uniform("vec4f", timeBuffer)
        }, `
            let idx = global_id.x;
            if (idx >= ${count}u) { return; }

            let time = params.x;
            let fIdx = f32(idx);
            let radius = 10.0 + (fIdx % 500.0) * 0.1;
            let angle = fIdx * 0.05 + time * (0.5 - radius * 0.005);

            // Write back Position (xyz) and Scale (w)
            instances[idx * 3u + 0u] = vec4f(cos(angle) * radius, sin(time + radius * 0.2) * 5.0, sin(angle) * radius, 0.3);

            // Write back Color (rgba)
            instances[idx * 3u + 1u] = vec4f(sin(angle) * 0.5 + 0.5, cos(angle) * 0.5 + 0.5, 1.0, 1.0);
        `, [64, 1, 1]);

        const timeData = new Float32Array(1);
        const workgroups = Math.ceil(count / 64);

        this.always(() => {
            timeData[0] = this.time * 0.001;
            this.device.queue.writeBuffer(timeBuffer, 0, timeData);
            this.addCompute(kernel.dispatch(this.device, workgroups));
            this.invalidate();
        });
    }
}
